     ```

4. **Use JNDI in Spring Boot**:
   In your Spring Boot application, you need to configure the `JavaMailSender` bean to access the JNDI resource. Here’s an example of a configuration class that sets up the `JavaMailSender` using the JNDI resource:

   ```java
   import org.springframework.context.annotation.Bean;
   import org.springframework.context.annotation.Configuration;
   import org.springframework.mail.jndi.JndiObjectFactoryBean;
   import org.springframework.mail.javamail.JavaMailSender;
   import org.springframework.mail.javamail.JavaMailSenderImpl;

   import javax.mail.Session;

   @Configuration
   public class MailConfig {

       @Bean
       public JavaMailSender mailSender() throws Exception {
           JndiObjectFactoryBean jndiObjectFactoryBean = new JndiObjectFactoryBean();
           jndiObjectFactoryBean.setJndiName("java:comp/mail/support");
           jndiObjectFactoryBean.setLookupOnStartup(true);
           jndiObjectFactoryBean.setProxyInterface(Session.class);
           jndiObjectFactoryBean.afterPropertiesSet();
           Session session = (Session) jndiObjectFactoryBean.getObject();

           JavaMailSenderImpl mailSender = new JavaMailSenderImpl();
           mailSender.setSession(session);
