  var locale = [];

  for (var i = 0; i < obj.length; i++) {
    pointLoc.push({ lat: obj[i].lat, lng: obj[i].lng });
    labels.push(obj[i].con);
    descrip.push(obj[i].description);
    locale.push(obj[i].location);
  }

  for (var i = 0; i < pointLoc.length; i++) {
    var coords = pointLoc[i];
    var latLng = new google.maps.LatLng(coords.lat, coords.lng);
    var marker = new google.maps.Marker({
      position: latLng,
      map: map
    });

    var contentStr = '<div id="popcontent">' +
      '<div id="siteNotice">' +
      '</div>' +
      '<h1 id="firstHeading" class="firstHeading">' + descrip[i] + '</h1>' +
      '<p>' + locale[i] + ', ' + labels[i] + '</p>' +
      '</div>';

    var infoWindow = new google.maps.InfoWindow({
      maxWidth: 300
    });

    google.maps.event.addListener(marker, 'click', (function(marker, contentStr) {
      return function() {
        // Close the currently opened InfoWindow
        if (openInfoWindow) {
          openInfoWindow.close();
        }

        // Set content and open the new infoWindow
        infoWindow.setContent(contentStr);
        infoWindow.open(map, marker);

        // Update openInfoWindow reference to the newly opened one
        openInfoWindow = infoWindow;
      };
    })(marker, contentStr));
  }
}
```

### Key Changes and Explanation:
1. **Open InfoWindow Reference**: I’ve changed the way you're handling the `infoWindow`. Instead of creating a new `infoWindow` for each marker, I keep a single instance (`openInfoWindow`) that will be closed whenever a new marker is clicked.

2. **Closure**: The inner closure of the event listener captures the `marker` and `contentStr` correctly, maintaining their values without leaking them outside the loop, which is a common JavaScript closure issue.

3. **Conditional Close**: Before opening a new `infoWindow`, we check if an `openInfoWindow` already exists and call `.close()` on it, ensuring only one `infoWindow` is displayed at any time.

These changes should resolve the problem you’re experiencing, making sure that each click on a marker will close any previously opened infoWindow before opening a new one.

