import Foundation

// Define an enum to represent acceptance and rejection states
enum UserResponse: Codable {
    case accept(String)
    case reject(String)

    // For decoding purposes, you must implement the CodingKeys and init(from decoder:) method
    private enum CodingKeys: String, CodingKey {
        case accept
        case reject
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)

        if let acceptMessage = try? container.decode(String.self, forKey: .accept) {
            self = .accept(acceptMessage)
        } else if let rejectMessage = try? container.decode(String.self, forKey: .reject) {
            self = .reject(rejectMessage)
        } else {
            throw DecodingError.dataCorruptedError(forKey: .accept, in: container, debugDescription: "Invalid user response")
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)

        switch self {
        case .accept(let message):
            try container.encode(message, forKey: .accept)
        case .reject(let message):
            try container.encode(message, forKey: .reject)
        }
    }
}

