Q: Loading Core Data database created by iOS app into different Xcode application
A: <p>Thanks to some of the recommendations from Lou Franco, I have found my way to a working solution. I grabbed the .momd file from the original app by archiving it and exploring the exported .app file in the .xcarchive. Here is a minimal example that loads data from an existing sqlite database at "/Path/To/Data/MyData.sqlite" using the data model from "/Path/To/Data/MyData.momd". It simply grabs all of the unique session IDs:</p>

<pre><code>import Foundation
import CoreData

let storePath = "/Path/To/Data/MyData.sqlite"
let storeURL = URL(fileURLWithPath: storePath)

let modelPath =  "/Path/To/Data/MyData.momd"
let modelUrl = URL(fileURLWithPath: modelPath)
let mom = NSManagedObjectModel(contentsOf: modelUrl)!

let psc = NSPersistentStoreCoordinator(managedObjectModel: mom)

let managedObjectContext = NSManagedObjectContext(concurrencyType: NSManagedObjectContextConcurrencyType.mainQueueConcurrencyType)
managedObjectContext.persistentStoreCoordinator = psc

try psc.addPersistentStore(ofType: NSSQLiteStoreType, configurationName: nil, at: storeURL, options: nil)

let request: NSFetchRequest&lt;Session&gt; = Session.fetchRequest()
request.sortDescriptors = [NSSortDescriptor(key: "uniqueSessionID", ascending: true)]
let context = managedObjectContext
do {
    let dbReturn = try context.fetch(request)
    print(dbReturn)
}
</code></pre>

